    private void refreshDeathCoffer()
    {
        String profile = configManager.getRSProfileKey();
        if (!Objects.equals(profile, deathCofferProfile))
        {
            deathCofferProfile = profile;
            deathCofferValue = Integer.MIN_VALUE;
            Integer saved = configManager.getRSProfileConfiguration("bowlsofmayo", DEATH_COFFER_BALANCE_KEY, int.class);
            if (saved != null && saved >= 0)
            {
                deathCofferValue = saved;
            }
            publishDeathCofferValue();
        }
        if (profile == null)
        {
            return;
        }
        // IF1 is reused by other interfaces; only the visible coffer's rendered balance is authoritative.
        Widget coffer = client.getWidget(InterfaceID.DeathCoffer.LEFT);
        if (coffer == null || coffer.isHidden())
        {
            return;
        }
        Widget balance = coffer.getChild(0);
        if (balance == null || balance.isHidden())
        {
            return;
        }
        String text = balance.getText();
        Integer value = parseDeathCofferBalance(text);
        if (value == null)
        {
            if (!Objects.equals(text, unrecognizedCofferText))
            {
                LOG.warn("Cannot read Death's Coffer balance: unrecognized interface text");
                unrecognizedCofferText = text;
            }
            return;
        }
        unrecognizedCofferText = null;
        if (value != deathCofferValue)
        {
            configManager.setRSProfileConfiguration("bowlsofmayo", DEATH_COFFER_BALANCE_KEY, value);
            updateDeathCofferValue(value);
        }
    }

    static Integer parseDeathCofferBalance(String text)
    {
        if (text == null)
        {
            return null;
        }
        Matcher matcher = DEATH_COFFER_TEXT.matcher(Text.removeTags(text).replace('\u00a0', ' ').trim());
        if (!matcher.matches())
        {
            return null;
        }
        if (matcher.group(1).equals("Empty"))
        {
            return 0;
        }
        String digits = matcher.group(1).split(" ")[0].replace(",", "");
        if (digits.length() > 10)
        {
            return null;
        }
        long value = Long.parseLong(digits);
        return value <= Integer.MAX_VALUE ? (int) value : null;
    }

    private void updateDeathCofferValue(int value)
    {
        if (deathCofferValue == value)
        {
            return;
        }
        int previousValue = deathCofferValue;
        deathCofferValue = value;
        if (config.notifyDeathCofferLow() &&
            crossedDeathCofferThreshold(previousValue, value, config.deathCofferLowThreshold()))
        {
            notifier.notify(String.format("Death's Coffer is low: %,d gp remaining.", value));
        }
        publishDeathCofferValue();
    }

    private void publishDeathCofferValue()
    {
        int value = deathCofferValue;
        String profile = deathCofferProfile;
        int expectedGeneration = generation;
        SwingUtilities.invokeLater(() -> {
            if (active(expectedGeneration) && panel != null && config.trackDeathCoffer() &&
                deathCofferValue == value && Objects.equals(profile, deathCofferProfile))
            {
                if (value == Integer.MIN_VALUE)
                {
                    panel.clearDeathCofferValue();
                }
                else
                {
                    panel.setDeathCofferValue(value);
                }
            }
        });
    }

    static boolean crossedDeathCofferThreshold(int previousValue, int value, int threshold)
    {
        return previousValue != Integer.MIN_VALUE && previousValue > threshold && value <= threshold;
    }

    @Subscribe
    public void onChatMessage(ChatMessage message)
    {
        if (account == null)
        {
            return;
        }
        String text = Text.removeTags(message.getMessage());
        if (message.getType() == ChatMessageType.CLAN_GIM_CHAT && config.shareChat() &&
            FeatureParser.samePlayer(Text.removeTags(message.getName()), account))
        {
            // Relay only the sender's own messages to avoid duplicates across group clients.
            TrackerData.Event event = event("chat");
            event.message = text;
            enqueue(event);
        }
        if (message.getType() != ChatMessageType.GAMEMESSAGE)
        {
            return;
        }
        String diary = FeatureParser.parseDiary(text);
        if (diary != null)
        {
            if (config.questAlerts())
            {
                TrackerData.Event event = event("diary");
                event.id = "diary:" + FeatureParser.sourceKey(diary);
                event.diary = diary;
                enqueue(event);
            }
            return;
        }
        FeatureParser.Kill kill = FeatureParser.parseKill(text);
        if (kill == null)
        {
            return;
        }
        FeatureParser.Kill previous = kills.put(FeatureParser.sourceKey(kill.boss), kill);
        if (config.bossAlerts() && !FeatureParser.isChestCount(kill.boss) && (previous == null || previous.kc != kill.kc))
        {
            TrackerData.Event event = event("boss");
            event.id = "boss:" + FeatureParser.sourceKey(kill.boss) + ":" + kill.kc;
            event.boss = kill.boss;
            event.kc = kill.kc;
            enqueue(event);
        }
    }

    @Subscribe
    public void onLootReceived(LootReceived received)
    {
        if (account == null || !config.dropAlerts() || received.getType().name().equals("PLAYER"))
        {
            return;
        }
        TrackerData.Event event = event("loot");
        event.source = received.getName();
        event.items = new ArrayList<>();
        for (ItemStack item : received.getItems())
        {
            if (item.getId() <= 0 || item.getQuantity() <= 0)
            {
                continue;
            }
            int price = (int) Math.min(Integer.MAX_VALUE, Math.max(0, itemManager.getItemPrice(item.getId())));
            if ((long) price * item.getQuantity() < config.minimumDropValue())
            {
                continue;
            }
            TrackerData.BankItem entry = new TrackerData.BankItem();
            entry.id = item.getId();
            entry.qty = item.getQuantity();
            entry.name = itemManager.getItemComposition(item.getId()).getName();
            entry.price = (long) price;
            event.items.add(entry);
        }
        if (!event.items.isEmpty())
        {
            loot.add(new PendingLoot(event, ticks + 3));
        }
    }

    private void flushLoot(boolean force)
    {
        loot.removeIf(pending -> {
            if (!force && pending.tick > ticks)
            {
                return false;
            }
            FeatureParser.Kill kill = kills.get(FeatureParser.sourceKey(pending.event.source));
            if (kill != null && System.currentTimeMillis() - kill.observedAt < 15000)
            {
                pending.event.kc = kill.kc;
            }
            enqueue(pending.event);
            return true;
        });
    }

    private TrackerData.Event event(String type)
    {
        TrackerData.Event event = new TrackerData.Event();
        event.id = UUID.randomUUID().toString();
        event.username = account;
        event.type = type;
        return event;
    }

    private void enqueue(TrackerData.Event event)
    {
        synchronized (uploadStateLock)
        {
            if (!running || accessResetPending || !config.enableConnection() || !UploadCoordinator.eventEnabled(config, event))
            {
                return;
            }
            if (events.size() >= 2000)
            {
                LOG.error("BowlsofMayo alert queue full; cannot queue {} alert", event.type);
                showStatus("Alert queue full! Check bridge connection.");
                return;
            }
            events.add(event);
        }
    }

    private boolean active(int expectedGeneration)
    {
        return running && generation == expectedGeneration;
    }

    private boolean canSync(int expectedGeneration, int expectedAccessRevision)
    {
        return active(expectedGeneration) && !accessResetPending && config.enableConnection() &&
            accessRevision == expectedAccessRevision;
    }

    private void synchronize(int expectedGeneration)
    {
        int expectedAccessRevision = accessRevision;
        if (!config.enableConnection())
        {
            clearGroupData("Connection disabled - no data sent.", expectedGeneration, expectedAccessRevision);
            return;
        }
        if (!active(expectedGeneration))
        {
            return;
        }
        try
        {
            BridgeClient bridge = new BridgeClient(http, config.serverUrl(), config.memberToken());
            TrackerData.Member current = snapshot;
            if (current != null && canSync(expectedGeneration, expectedAccessRevision))
            {
                String json = gson.toJson(UploadCoordinator.snapshotForUpload(config, current));
                if (!canSync(expectedGeneration, expectedAccessRevision))
                {
                    return;
                }
                bridge.post("/v1/snapshot", json);
            }
            String alertStatus = UploadCoordinator.sendAlerts(bridge, gson, events, config,
                () -> canSync(expectedGeneration, expectedAccessRevision));
            if (!canSync(expectedGeneration, expectedAccessRevision))
            {
                return;
            }
            showStatus(SyncStatus.Channel.ALERTS, alertStatus, expectedGeneration, expectedAccessRevision);
            TrackerData.Group group = gson.fromJson(bridge.get("/v1/group"), TrackerData.Group.class);
            if (group == null || group.members == null)
            {
                throw new IOException("Bridge returned an invalid group response");
            }
            clientThread.invokeLater(() -> {
                if (active(expectedGeneration) && accessRevision == expectedAccessRevision)
                {
                    groupMembers = group.members;
                    updateMap(group.members);
                    // Item definitions must be read on the client thread, not Swing's EDT.
                    TrackerData.Group panelGroup = tradeableView(group);
                    SwingUtilities.invokeLater(() -> {
                        if (active(expectedGeneration) && accessRevision == expectedAccessRevision)
                        {
                            panel.update(panelGroup);
                        }
                    });
                }
            });
            if (active(expectedGeneration))
            {
                showStatus(SyncStatus.Channel.GROUP, "", expectedGeneration, expectedAccessRevision);
            }
            uploadBankIcons(bridge, current, group, expectedGeneration, expectedAccessRevision);
            refreshRemoteImages(bridge, expectedGeneration, expectedAccessRevision);
        }
        catch (IOException | IllegalArgumentException | com.google.gson.JsonParseException error)
        {
            LOG.warn("BowlsofMayo bridge sync failed: {}", error.getMessage());
            clearGroupData("Not synced: " + error.getMessage(), expectedGeneration, expectedAccessRevision);
        }
    }

    private TrackerData.Group tradeableView(TrackerData.Group group)
    {
        TrackerData.Group view = new TrackerData.Group();
        view.icons = group.icons;
        view.viewer = group.viewer;
        view.members = new ArrayList<>();
        for (TrackerData.Member member : group.members)
        {
            TrackerData.Member copy = new TrackerData.Member();
            copy.username = member.username;
            copy.bank = tradeableItems(member.bank);
            copy.bankShared = member.bankShared;
            copy.bankUpdatedAt = member.bankUpdatedAt;
            view.members.add(copy);
        }
        if (group.groupStorage != null)
        {
            view.groupStorage = new TrackerData.GroupStorage();
            view.groupStorage.items = tradeableItems(group.groupStorage.items);
            view.groupStorage.updatedAt = group.groupStorage.updatedAt;
            view.groupStorage.username = group.groupStorage.username;
        }
        return view;
    }

    private List<TrackerData.BankItem> tradeableItems(List<TrackerData.BankItem> items)
    {
        if (items == null)
        {
            return null;
        }
        List<TrackerData.BankItem> tradeable = new ArrayList<>(items.size());
        for (TrackerData.BankItem item : items)
        {
            if (tradeableCache.computeIfAbsent(item.id,
                id -> itemManager.getItemComposition(itemManager.canonicalize(id)).isTradeable()))
            {
                tradeable.add(item);
            }
        }
        return tradeable;
    }

    private void uploadBankIcons(BridgeClient bridge, TrackerData.Member current, TrackerData.Group group,
        int expectedGeneration, int expectedAccessRevision)
    {
        if (!canSync(expectedGeneration, expectedAccessRevision))
        {
            return;
        }
        try
        {
            if (current != null && current.bankShared && config.shareBank())
            {
                TrackerData.Icons upload = new TrackerData.Icons();
                upload.username = current.username;
                for (TrackerData.BankItem item : BankSnapshots.combinedItems(current.bank, current.groupStorage))
                {
                    String image = bankSnapshots.icon(item.id);
                    if (image != null && (group.icons == null || !group.icons.containsKey(item.id)))
                    {
                        upload.icons.put(item.id, image);
                        if (upload.icons.size() == 32)
                        {
                            break;
                        }
                    }
                }
                if (!upload.icons.isEmpty() && config.shareBank() && canSync(expectedGeneration, expectedAccessRevision))
                {
                    bridge.post("/v1/icons", gson.toJson(upload));
                }
            }
            showStatus(SyncStatus.Channel.BANK_ICONS, "", expectedGeneration, expectedAccessRevision);
        }
        catch (IOException error)
        {
            LOG.warn("Bank icons not synced: {}", error.getMessage());
            showStatus(SyncStatus.Channel.BANK_ICONS, "Bank icons not synced; will retry: " +
                error.getMessage(), expectedGeneration, expectedAccessRevision);
        }
    }

    private void clearGroupData(String message, int expectedGeneration, int expectedAccessRevision)
    {
        SwingUtilities.invokeLater(() -> {
            if (active(expectedGeneration) && accessRevision == expectedAccessRevision)
            {
                syncStatus.set(SyncStatus.Channel.GROUP, message);
                panel.clear(syncStatus.text());
                panel.setConnectionEnabled(config.enableConnection());
            }
        });
        clientThread.invokeLater(() -> {
            if (active(expectedGeneration) && accessRevision == expectedAccessRevision)
            {
                groupMembers = Collections.emptyList();
                mapManager.removeIf(GroupMapPoint.class::isInstance);
            }
        });
    }

    private void updateMap(List<TrackerData.Member> members)
    {
        mapManager.removeIf(GroupMapPoint.class::isInstance);
        if (!config.showMap() || client.getGameState() != GameState.LOGGED_IN)
        {
            return;
        }
        for (TrackerData.Member member : members)
        {
            TrackerData.Position position = member.position;
            if (position == null || System.currentTimeMillis() - member.updatedAt > 30000 ||
                FeatureParser.samePlayer(member.username, account))
            {
                continue;
            }
            GroupMapPoint point = new GroupMapPoint(
                new WorldPoint(position.x, position.y, position.plane), mapMarker());
            point.setName(member.username);
            point.setTooltip(member.username + " - World " + position.world +
                (position.world == client.getWorld() ? "" : " (different world)"));
            point.setSnapToEdge(true);
            point.setJumpOnClick(true);
            mapManager.add(point);
        }

        Player localPlayer = client.getLocalPlayer();
        if (localPlayer != null)
        {
            WorldPoint position = WorldPoint.fromLocalInstance(client, localPlayer.getLocalLocation());
            GroupMapPoint point = new GroupMapPoint(position, mapMarker());
            point.setName("You");
            point.setTooltip((account == null ? localPlayer.getName() : account) +
                " - World " + client.getWorld());
            point.setSnapToEdge(true);
            point.setJumpOnClick(true);
            mapManager.add(point);
        }
    }

    private void showStatus(String status)
    {
        showStatus(SyncStatus.Channel.ALERTS, status, generation, accessRevision);
    }

    private void showStatus(SyncStatus.Channel channel, String status, int expectedGeneration, int expectedAccessRevision)
    {
        SwingUtilities.invokeLater(() -> {
            if (active(expectedGeneration) && accessRevision == expectedAccessRevision)
            {
                syncStatus.set(channel, status);
                panel.setStatus(syncStatus.text());
            }
        });
    }

    @Subscribe
    public void onConfigChanged(ConfigChanged event)
    {
        if (!"bowlsofmayo".equals(event.getGroup()))
        {
            return;
        }
        switch (event.getKey())
        {
            case "deathCofferLowThreshold":
                SwingUtilities.invokeLater(() -> {
                    if (panel != null)
                    {
                        panel.setDeathCofferThreshold(config.deathCofferLowThreshold());
                    }
                });
                break;
            case "trackDeathCoffer":
                SwingUtilities.invokeLater(() -> {
                    if (panel != null)
                    {
                        panel.setDeathCofferVisible(config.trackDeathCoffer());
                    }
                });
                break;
            case "enableConnection":
                resetUploadAccess();
                clearGroupData(config.enableConnection() ? "Waiting for sync." :
                    "Connection disabled - no data sent.", generation, accessRevision);
                break;
            case "shareLiveXp":
            case "shareBank":
            case "shareStorageWithdrawals":
            case "shareLocation":
            case "shareChat":
            case "bossAlerts":
            case "dropAlerts":
            case "questAlerts":
                synchronized (uploadStateLock)
                {
                    accessRevision++;
                    snapshot = null;
                    events.removeIf(queued -> !UploadCoordinator.eventEnabled(config, queued));
                }
                if (event.getKey().equals("shareLiveXp"))
                {
                    liveXp.discardPending();
                    clientThread.invokeLater(liveXp::clear);
                    showStatus(SyncStatus.Channel.XP, "", generation, accessRevision);
                    showStatus(SyncStatus.Channel.XP_EXPIRY, "", generation, accessRevision);
                }
                if (event.getKey().equals("shareBank"))
                {
                    clientThread.invokeLater(() -> {
                        bank = null;
                        bankUpdatedAt = 0;
                        groupStorage = null;
                        groupStorageUpdatedAt = 0;
                    });
                }
                if (event.getKey().equals("dropAlerts"))
                {
                    clientThread.invokeLater(loot::clear);
                }
                break;
            case "serverUrl":
            case "memberToken":
                resetUploadAccess();
                clearGroupData("Access changed - waiting for sync.", generation, accessRevision);
                logo = null;
                mapIcon = null;
                mapIconFetchedAt = 0;
                logoFetchedAt = 0;
                refreshSidebarIcon();
                break;
            case "sidebarIcon":
            case "sidebarItemId":
                logoFetchedAt = 0;
                showStatus(SyncStatus.Channel.LOGO_IMAGE, "", generation, accessRevision);
                refreshSidebarIcon();
                break;
            default:
                break;
        }
    }

    private void resetUploadAccess()
    {
        synchronized (uploadStateLock)
        {
            accessResetPending = true;
            accessRevision++;
            snapshot = null;
            events.clear();
            liveXp.discardPending();
        }
        nextXpAttempt = 0;
        int expectedGeneration = generation;
        int expectedAccessRevision = accessRevision;
        SwingUtilities.invokeLater(() -> {
            if (active(expectedGeneration) && accessRevision == expectedAccessRevision)
            {
                syncStatus.clear();
                panel.setStatus("");
            }
        });
        clientThread.invokeLater(() -> {
            synchronized (uploadStateLock)
            {
                if (!active(expectedGeneration))
                {
                    return;
                }
                resetAccount();
                accessResetPending = false;
            }
        });
    }

    private void refreshSidebarIcon()
    {
        if (!running)
        {
            return;
        }
        SidebarIcon choice = config.sidebarIcon();
        if (choice == SidebarIcon.COMPANION_SHIELD)
        {
            setSidebarIcon(COMPANION_ICON);
            return;
        }
        if (choice == SidebarIcon.GROUP_LOGO)
        {
            BufferedImage current = logo;
            setSidebarIcon(current != null ? current : COMPANION_ICON);
            return;
        }
        if (choice == SidebarIcon.DOT)
        {
            setSidebarIcon(TrackerImages.marker());
            return;
        }
        int itemId = choice == SidebarIcon.CUSTOM_ITEM ? config.sidebarItemId() : choice.itemId();
        AsyncBufferedImage image = itemManager.getImage(itemId, choice.quantity(), choice.quantity() > 1);
        image.onLoaded(() -> {
            if (running && config.sidebarIcon() == choice)
            {
                setSidebarIcon(TrackerImages.iconImage(image));
            }
        });
    }

    private void refreshRemoteImages(BridgeClient bridge, int expectedGeneration, int expectedAccessRevision)
    {
        if (!canSync(expectedGeneration, expectedAccessRevision))
        {
            return;
        }
        if (System.currentTimeMillis() - mapIconFetchedAt > MAP_ICON_REFRESH_MILLIS)
        {
            mapIconFetchedAt = System.currentTimeMillis();
            try
            {
                fetchMapIcon(bridge, expectedGeneration, expectedAccessRevision);
                showStatus(SyncStatus.Channel.MAP_IMAGE, "", expectedGeneration, expectedAccessRevision);
            }
            catch (IOException error)
            {
                LOG.warn("Map icon unavailable: {}", error.getMessage());
                showStatus(SyncStatus.Channel.MAP_IMAGE, "Map icon unavailable; using cached/default icon: " +
                    error.getMessage(), expectedGeneration, expectedAccessRevision);
            }
        }
        if (canSync(expectedGeneration, expectedAccessRevision) && config.sidebarIcon() == SidebarIcon.GROUP_LOGO &&
            System.currentTimeMillis() - logoFetchedAt > LOGO_REFRESH_MILLIS)
        {
            logoFetchedAt = System.currentTimeMillis();
            fetchLogo(bridge, expectedGeneration, expectedAccessRevision);
        }
    }

    private void fetchLogo(BridgeClient bridge, int expectedGeneration, int expectedAccessRevision)
    {
        try
        {
            BufferedImage image = TrackerImages.readLogo(bridge);
            synchronized (uploadStateLock)
            {
                if (canSync(expectedGeneration, expectedAccessRevision))
                {
                    logo = image;
                    if (config.sidebarIcon() == SidebarIcon.GROUP_LOGO)
                    {
                        setSidebarIcon(logo);
                    }
                    showStatus(SyncStatus.Channel.LOGO_IMAGE, "", expectedGeneration, expectedAccessRevision);
                }
            }
        }
        catch (IOException error)
        {
            LOG.warn("Group logo unavailable: {}", error.getMessage());
            showStatus(SyncStatus.Channel.LOGO_IMAGE, "Group logo unavailable; using cached/default icon: " +
                error.getMessage(), expectedGeneration, expectedAccessRevision);
        }
    }

    private BufferedImage mapMarker()
    {
        BufferedImage current = mapIcon;
        return current != null ? current : TrackerImages.marker();
    }

    private void fetchMapIcon(BridgeClient bridge, int expectedGeneration, int expectedAccessRevision) throws IOException
    {
        BufferedImage image = TrackerImages.readMapIcon(bridge);
        clientThread.invokeLater(() -> {
            if (canSync(expectedGeneration, expectedAccessRevision))
            {
                mapIcon = image;
                updateMap(groupMembers);
            }
        });
    }

    private void setSidebarIcon(BufferedImage icon)
    {
        int expectedGeneration = generation;
        int expectedAccessRevision = accessRevision;
        SwingUtilities.invokeLater(() -> {
            if (!active(expectedGeneration) || accessRevision != expectedAccessRevision || panel == null)
            {
                return;
            }
            NavigationButton previous = button;
            button = NavigationButton.builder().tooltip("Group Iron Companion")
                .icon(icon).priority(7).panel(panel).build();
            if (previous != null)
            {
                toolbar.removeNavigation(previous);
            }
            toolbar.addNavigation(button);
        });
    }

