        plugin.onChatMessage(chat(ChatMessageType.PUBLICCHAT, "Test Player", "Do not relay"));
        plugin.onChatMessage(chat(ChatMessageType.PRIVATECHAT, "Test Player", "Do not relay"));
        plugin.onChatMessage(chat(ChatMessageType.CLAN_CHAT, "Test Player", "Do not relay"));
        plugin.onChatMessage(chat(ChatMessageType.CLAN_GIM_CHAT, "Other Player", "Not our message"));
        assert events.isEmpty() : "Unrelated chat leaked";
        plugin.onChatMessage(chat(ChatMessageType.CLAN_GIM_CHAT, "<img=1>Test_Player", "Hello group"));
        assert events.size() == 1;
        Object first = events.poll();
        assert first instanceof TrackerData.Event;
        assert ((TrackerData.Event) first).message.equals("Hello group");
        plugin.onChatMessage(chat(ChatMessageType.GAMEMESSAGE, "", "Your Zulrah kill count is: <col=ff0000>127</col>."));
        plugin.onChatMessage(chat(ChatMessageType.GAMEMESSAGE, "", "Your Zulrah kill count is: <col=ff0000>127</col>."));
        assert events.size() == 1 : "Repeated KC should not create multiple alerts";
        events.clear();
        plugin.onChatMessage(chat(ChatMessageType.GAMEMESSAGE, "", "Your Lunar Chest count is: 12."));
        assert events.isEmpty() : "Lunar Chest must not create a boss alert";
        plugin.onChatMessage(chat(ChatMessageType.GAMEMESSAGE, "",
            "Congratulations! You have completed all of the hard tasks in the Varrock area."));
        assert events.size() == 1;
        TrackerData.Event diary = (TrackerData.Event) events.poll();
        assert diary.type.equals("diary") && diary.diary.equals("Varrock Hard");
        assert UploadCoordinator.eventEnabled(new ClanTrackerConfig() {
            public boolean questAlerts() { return true; }
        }, diary);
        assert !UploadCoordinator.eventEnabled(new ClanTrackerConfig() {}, diary);

        int[] currentQuest = new int[1];
        int[] completedQuest = {-1};
        WorldView worldView = (WorldView) Proxy.newProxyInstance(WorldView.class.getClassLoader(),
            new Class<?>[]{WorldView.class}, (proxy, method, arguments) -> {
                if (method.getName().equals("getBaseX"))
                {
                    return 3200;
                }
                if (method.getName().equals("getBaseY"))
                {
                    return 3200;
                }
                if (method.getName().equals("getPlane"))
                {
                    return 0;
                }
                if (method.getName().equals("isInstance"))
                {
                    return false;
                }
                throw new AssertionError("Unexpected world view access: " + method.getName());
            });
        Client client = (Client) Proxy.newProxyInstance(Client.class.getClassLoader(), new Class<?>[]{Client.class},
            (proxy, method, arguments) -> {
                if (method.getName().equals("runScript"))
                {
                    Object[] scriptArguments = (Object[]) arguments[0];
                    currentQuest[0] = ((Number) scriptArguments[1]).intValue();
                    return null;
                }
                if (method.getName().equals("getIntStack"))
                {
                    return new int[]{currentQuest[0] == completedQuest[0] ? 2 : 1};
                }
                if (method.getName().equals("getGameState"))
                {
                    return GameState.LOGGED_IN;
                }
                if (method.getName().equals("getWidget"))
                {
                    return null;
                }
                if (method.getName().equals("getWorld"))
                {
                    return 444;
                }
                if (method.getName().equals("getWorldView") ||
                    method.getName().equals("getTopLevelWorldView"))
                {
                    return worldView;
                }
                if (method.getName().equals("getLocalPlayer"))
                {
                    return Proxy.newProxyInstance(Player.class.getClassLoader(), new Class<?>[]{Player.class},
                        (playerProxy, playerMethod, playerArguments) -> {
                            if (playerMethod.getName().equals("getLocalLocation"))
                            {
                                return LocalPoint.fromScene(10, 20);
                            }
                            if (playerMethod.getName().equals("getName"))
                            {
                                return "Test Player";
                            }
                            throw new AssertionError("Unexpected player access: " + playerMethod.getName());
                        });
                }
                if (method.getName().equals("getRealSkillLevel"))
                {
                    return 99;
                }
                if (method.getName().equals("getSkillExperience"))
                {
                    return 13034431;
                }
                if (method.getName().equals("getVarpValue") && ((Number) arguments[0]).intValue() == VarPlayerID.QP)
                {
                    return 40;
                }
                if (method.getName().equals("getVarbitValue"))
                {
                    return 0;
                }
                throw new AssertionError("Unexpected client access: " + method.getName());
            });
        set(plugin, "client", client);
        Method checkQuests = ClanTrackerPlugin.class.getDeclaredMethod("checkQuests");
        checkQuests.setAccessible(true);
        checkQuests.invoke(plugin);
        assert events.isEmpty() : "Quest login baseline generated alerts";
        completedQuest[0] = Quest.values()[0].getId();
        checkQuests.invoke(plugin);
        assert events.size() == 1 : "Quest completion should generate one alert";
        checkQuests.invoke(plugin);
        assert events.size() == 1 : "Unchanged quest generated another alert";

        ItemContainer emptyBank = (ItemContainer) Proxy.newProxyInstance(ItemContainer.class.getClassLoader(),
            new Class<?>[]{ItemContainer.class}, (proxy, method, arguments) -> {
                if (method.getName().equals("getItems"))
                {
                    return new Item[0];
                }
                throw new AssertionError("Unexpected container access");
            });
        plugin.onItemContainerChanged(new ItemContainerChanged(InventoryID.INVENTORY.getId(), emptyBank));
        assert get(plugin, "snapshot") == null : "Inventory event should not collect bank";
        plugin.onItemContainerChanged(new ItemContainerChanged(InventoryID.BANK.getId(), emptyBank));
        TrackerData.Member captured = (TrackerData.Member) get(plugin, "snapshot");
        assert captured.bank != null && captured.bank.isEmpty() : "Empty bank should be shared";
        assert captured.bankUpdatedAt > 0;
        assert captured.stats.size() >= 23;
        assert captured.questPoints == 40 : "Quest points should be shared";
        assert captured.killCounts.equals(java.util.Map.of("zulrah", 127)) : "Only positive saved KCs should be shared";
        assert UploadCoordinator.snapshotForUpload(new ClanTrackerConfig() {}, captured).killCounts == null :
            "Saved KCs require boss-alert consent";
        assert UploadCoordinator.snapshotForUpload(new ClanTrackerConfig() {
            public boolean bossAlerts() { return true; }
        }, captured).killCounts.equals(captured.killCounts);
        assert captured.position == null : "Location sharing is disabled";
        plugin.onItemContainerChanged(new ItemContainerChanged(InventoryID.GROUP_STORAGE_INV.getId(), emptyBank));
        assert get(plugin, "snapshot") == captured : "Inventory shown beside group storage is not shared storage";
        plugin.onItemContainerChanged(new ItemContainerChanged(InventoryID.GROUP_STORAGE.getId(), emptyBank));
        captured = (TrackerData.Member) get(plugin, "snapshot");
        assert captured.groupStorage != null && captured.groupStorage.isEmpty() : "Empty group storage should sync";
        assert captured.groupStorageUpdatedAt > 0;
        assert captured.bank != null : "Group storage must not replace the personal bank";

        WorldMapPointManager manager = new WorldMapPointManager();
        set(plugin, "mapManager", manager);
        Method updateMap = ClanTrackerPlugin.class.getDeclaredMethod("updateMap", List.class);
        updateMap.setAccessible(true);
        TrackerData.Member other = new TrackerData.Member();
        other.username = "Other Player";
        other.updatedAt = System.currentTimeMillis();
        other.position = new TrackerData.Position();
        other.position.x = 3200;
        other.position.y = 3200;
        other.position.world = 445;
        TrackerData.Member self = new TrackerData.Member();
        self.username = "Test Player";
        self.updatedAt = other.updatedAt;
        self.position = other.position;
        updateMap.invoke(plugin, Arrays.asList(other, self));
        List<?> points = (List<?>) get(manager, "worldMapPoints");
        assert points.size() == 2 : "Teammate and local player should have markers";
        WorldMapPoint point = (WorldMapPoint) points.get(0);
        assert point.getTooltip().contains("different world");
        assert point.getWorldPoint().getX() == 3200;
        WorldMapPoint selfPoint = (WorldMapPoint) points.get(1);
        assert selfPoint.getName().equals("You");
        assert selfPoint.getWorldPoint().equals(new WorldPoint(3210, 3220, 0));
        other.updatedAt -= 31000;
        BufferedImage customMarker = new BufferedImage(32, 32, BufferedImage.TYPE_INT_ARGB);
        set(plugin, "mapIcon", customMarker);
        updateMap.invoke(plugin, Arrays.asList(other, self));
        assert ((WorldMapPoint) points.get(0)).getImage() == customMarker :
            "The local marker must use the website map icon";
        other.updatedAt += 31000;
        updateMap.invoke(plugin, Arrays.asList(other, self));
        assert points.size() == 2;
        assert ((WorldMapPoint) points.get(0)).getImage() == customMarker &&
            ((WorldMapPoint) points.get(1)).getImage() == customMarker :
            "Both teammate and local markers must use the website map icon";
        set(plugin, "mapIcon", null);
        other.updatedAt -= 31000;
        updateMap.invoke(plugin, Arrays.asList(other, self));
        assert ((WorldMapPoint) points.get(0)).getImage().getWidth() == 16 :
            "Without a downloaded map icon the original dot must remain available";
        assert points.size() == 1 && ((WorldMapPoint) points.get(0)).getName().equals("You") :
            "Stale teammate markers must expire while the local marker remains";
    }

    private static void checkLiveXp() throws Exception
    {
        LiveXpTracker tracker = new LiveXpTracker();
        long now = System.currentTimeMillis();
        tracker.observe("Test Player", new net.runelite.api.events.StatChanged(net.runelite.api.Skill.MINING, 1000, 9, 9),
            9, true, now);
        assert !tracker.hasPending() : "Login XP is a baseline, not a drop";
        tracker.observe("Test Player", new net.runelite.api.events.StatChanged(net.runelite.api.Skill.MINING, 1035, 9, 9),
            9, true, now);
        assert tracker.batch(now).drops.size() == 1;
        assert tracker.batch(now).drops.get(0).amount == 35 : "Mining drop must be exactly +35";
        tracker.observe("Test Player", new net.runelite.api.events.StatChanged(net.runelite.api.Skill.MINING, 1035, 9, 15),
            9, true, now);
        assert tracker.batch(now).drops.size() == 1 : "Boosted levels must not create XP";
        tracker.observe("Test Player", new net.runelite.api.events.StatChanged(net.runelite.api.Skill.MINING, 1070, 9, 9),
            9, false, now);
        tracker.observe("Test Player", new net.runelite.api.events.StatChanged(net.runelite.api.Skill.MINING, 1105, 9, 9),
            9, true, now);
        assert tracker.batch(now).drops.get(1).amount == 35 : "Disabled XP must not be replayed";
        tracker.clearBaseline();
        tracker.observe("Test Player", new net.runelite.api.events.StatChanged(net.runelite.api.Skill.MINING, 1200, 10, 10),
            10, true, now);
        assert tracker.batch(now).drops.size() == 2 : "World hop must establish a new baseline";
        tracker.clear();
        assert !tracker.hasPending();
        tracker.baseline(net.runelite.api.Skill.MINING, 1200);
        tracker.observe("Test Player", new net.runelite.api.events.StatChanged(net.runelite.api.Skill.MINING, 1235, 10, 10),
            10, true, now);
        String id = tracker.batch(now).drops.get(0).id;
        com.sun.net.httpserver.HttpServer server = com.sun.net.httpserver.HttpServer.create(
            new java.net.InetSocketAddress("127.0.0.1", 0), 0);
        int[] status = {500};
        String[] body = {""};
        server.createContext("/v1/xp-drops", exchange -> {
            body[0] = new String(exchange.getRequestBody().readAllBytes(), java.nio.charset.StandardCharsets.UTF_8);
            byte[] response = "{}".getBytes(java.nio.charset.StandardCharsets.UTF_8);
            exchange.sendResponseHeaders(status[0], response.length);
            exchange.getResponseBody().write(response);
            exchange.close();
        });
        server.start();
        try
        {
            BridgeClient bridge = new BridgeClient(new OkHttpClient(),
                "http://127.0.0.1:" + server.getAddress().getPort(), "a".repeat(48));
            Gson gson = new Gson();
            try
            {
                tracker.send(bridge, gson, tracker.batch(now));
                throw new AssertionError("Failed upload must throw");
            }
            catch (java.io.IOException expected)
            {
                assert tracker.hasPending() : "Failed uploads must remain queued";
            }
            status[0] = 200;
            tracker.send(bridge, gson, tracker.batch(now));
            assert !tracker.hasPending() : "Successful upload must acknowledge drops";
            assert body[0].contains(id) && body[0].contains("\"amount\":35");
            tracker.baseline(net.runelite.api.Skill.FISHING, 1000);
            tracker.observe("Test Player", new net.runelite.api.events.StatChanged(net.runelite.api.Skill.FISHING, 1020, 9, 9),
                9, true, now);
            assert tracker.batch(now + 26000).drops.isEmpty() : "Expired drops must not look live";
        }
        finally
        {
            server.stop(0);
        }
    }

    private static ChatMessage chat(ChatMessageType type, String name, String message)
    {
        ChatMessage event = new ChatMessage();
        event.setType(type);
        event.setName(name);
        event.setMessage(message);
        return event;
    }

    private static void set(Object instance, String name, Object value) throws Exception
    {
        Field field = instance.getClass().getDeclaredField(name);
        field.setAccessible(true);
        field.set(instance, value);
    }

    private static Object get(Object instance, String name) throws Exception
    {
        Field field = instance.getClass().getDeclaredField(name);
        field.setAccessible(true);
        return field.get(instance);
    }

    private static void checkKill(String message, String boss, int count)
    {
        FeatureParser.Kill kill = FeatureParser.parseKill(message);
        assert kill != null : message;
        assert kill.boss.equals(boss) : kill.boss;
        assert kill.kc == count : kill.kc;
    }

    private static void rejects(Runnable action)
    {
        try
        {
            action.run();
            throw new AssertionError("Expected configuration rejection");
        }
        catch (IllegalArgumentException expected)
        {
            assert expected.getMessage() != null;
        }
    }
}

package com.bowlsofmayo;

import java.awt.Component;
import java.awt.Container;
import java.lang.reflect.Field;
import java.lang.reflect.Method;
import java.lang.reflect.Proxy;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;
import java.util.concurrent.atomic.AtomicInteger;
import javax.swing.JButton;
import javax.swing.JComboBox;
import javax.swing.JPanel;
import javax.swing.JTextField;
import javax.swing.SwingUtilities;
import javax.swing.Timer;
import net.runelite.api.Client;
import net.runelite.api.Item;
import net.runelite.api.ItemComposition;
import net.runelite.api.ItemContainer;
import net.runelite.client.game.ItemManager;

final class SidebarChecks
{
    static void run() throws Exception
    {
        AtomicInteger definitions = new AtomicInteger();
        Client client = (Client) Proxy.newProxyInstance(Client.class.getClassLoader(), new Class<?>[]{Client.class},
            (proxy, method, arguments) -> {
                if (method.getName().equals("isClientThread")) return false;
                if (method.getName().equals("getItemDefinition"))
                {
                    definitions.incrementAndGet();
                    int id = (int) arguments[0];
                    return Proxy.newProxyInstance(ItemComposition.class.getClassLoader(),
                        new Class<?>[]{ItemComposition.class}, (definition, member, values) -> {
                            switch (member.getName())
                            {
                                case "getName": return "Item " + id;
                                case "getNote":
                                case "getPlaceholderTemplateId": return -1;
                                case "getHaPrice": return 10;
                                case "isTradeable": return id != 4151;
                                default: throw new AssertionError("Unexpected item access: " + member.getName());
                            }
                        });
                }
                throw new AssertionError("Unexpected client access: " + method.getName());
            });
        ItemManager itemManager = TestServices.itemManager(client);
        checkTabCapture(itemManager);
        checkTradeableView(itemManager, definitions);
        SwingUtilities.invokeAndWait(() -> checkLargeBank(itemManager));
        System.out.println("Sidebar regression checks passed (800 items, unchanged-sync reuse, debounce, tabs, permissions, tradeable filter).");
    }

    private static void checkTabCapture(ItemManager itemManager)
    {
        Item[] items = {new Item(995, 10), new Item(1000, 0), new Item(4151, 1), new Item(1001, 1)};
        ItemContainer container = (ItemContainer) Proxy.newProxyInstance(ItemContainer.class.getClassLoader(),
            new Class<?>[]{ItemContainer.class}, (proxy, method, arguments) -> {
                if (method.getName().equals("getItems")) return items;
                throw new AssertionError("Unexpected container access: " + method.getName());
            });
        BankSnapshots snapshots = new BankSnapshots();
        List<TrackerData.BankItem> bank = snapshots.readItems(itemManager, container, new int[]{2, 1});
        assert bank.size() == 3 : "Placeholders should not upload";
        assert bank.get(0).tab == 1 && bank.get(1).tab == 2 && bank.get(2).tab == 0 :
            "Placeholder slots must still count toward tab boundaries";
        assert snapshots.readItems(itemManager, container).stream().allMatch(item -> item.tab == null) :
            "Group storage has no personal bank tabs";
    }

    private static void checkTradeableView(ItemManager itemManager, AtomicInteger definitions) throws Exception
    {
        ClanTrackerPlugin plugin = new ClanTrackerPlugin();
        set(plugin, "itemManager", itemManager);
        TrackerData.Group group = group(2);
        group.members.get(0).bank.get(0).id = 995;
        group.members.get(0).bank.get(1).id = 4151;
        group.groupStorage = new TrackerData.GroupStorage();
        group.groupStorage.items = group.members.get(0).bank;
        group.groupStorage.username = "Test Player";
        Method filter = ClanTrackerPlugin.class.getDeclaredMethod("tradeableView", TrackerData.Group.class);
        filter.setAccessible(true);
        TrackerData.Group view = (TrackerData.Group) filter.invoke(plugin, group);
        assert view.members.get(0).bank.size() == 1 && view.groupStorage.items.size() == 1;
        assert view.members.get(0).bank.get(0).tab == 1 : "Filtering must preserve bank tabs";
        assert group.members.get(0).bank.size() == 2 : "Sidebar filtering must not change uploaded bank data";
        int reads = definitions.get();
        filter.invoke(plugin, group);
        assert definitions.get() == reads : "Unchanged syncs must reuse cached tradeability";
    }

    private static void checkLargeBank(ItemManager itemManager)
    {
        try
        {
            ClanPanel panel = new ClanPanel(itemManager);
            TrackerData.Group group = group(800);
            panel.update(group);
            JPanel contents = (JPanel) get(panel, "contents");
            JComboBox<?> selector = (JComboBox<?>) get(panel, "selector");
            assert tiles(contents) == 800 : "All bank items must be visible initially";
            assert tab(contents, "Tab 1 (Item 10000)") != null && tab(contents, "Tab 4 (Item 10600)") != null;
            Component first = contents.getComponent(0);
            AtomicInteger selectorChanges = new AtomicInteger();
            selector.addActionListener(event -> selectorChanges.incrementAndGet());
            for (int i = 0; i < 20; i++) panel.update(group(800));
            assert contents.getComponent(0) == first : "Unchanged polling must reuse the existing bank UI";
            assert selectorChanges.get() == 0 : "Unchanged polling must not rebuild the selector";
            tab(contents, "Tab 2 (Item 10200)").doClick(0);
            assert tiles(contents) == 200 : "A bank tab must show only its items";
            panel.update(group);
            assert Integer.valueOf(2).equals(get(panel, "selectedTab")) : "Polling must preserve selected tab";
            tab(contents, "All items").doClick(0);
            rightClick(tab(contents, "Tab 2 (Item 10200)"));
            assert tiles(contents) == 600 : "Right-click must collapse only that tab";
            panel.update(group(800));
            assert tiles(contents) == 600 : "Polling must preserve collapsed tabs";
            tab(contents, "Tab 2 (Item 10200)").doClick(0);
            assert tiles(contents) == 0 : "Left-click must not reopen a collapsed tab";
            rightClick(tab(contents, "Tab 2 (Item 10200)"));
            assert tiles(contents) == 200 : "Right-click must expand the selected tab";
            tab(contents, "All items").doClick(0);
            rightClick(tab(contents, "Tab 1 (Item 10000)"));
            selector.setSelectedItem("Other Player");
            selector.setSelectedItem("Test Player");
            assert tiles(contents) == 600 : "Collapse state must be scoped to each member";
            rightClick(tab(contents, "Tab 1 (Item 10000)"));
            assert tiles(contents) == 800;

            JTextField search = (JTextField) get(panel, "search");
            search.setText("Item 10000");
            assert tiles(contents) == 800 : "Typing must defer the expensive rebuild";
            Timer timer = (Timer) get(panel, "searchDebounce");
            assert timer.isRunning() && timer.getInitialDelay() == 200 && !timer.isRepeats();
            fire(timer);
            assert tiles(contents) == 1 : "Debounced search must show the matching item";
            search.setText("");
            fire(timer);
            assert tiles(contents) == 800;

            group.members.get(0).bankUpdatedAt++;
            group.members.get(0).bank.get(0).qty++;
            first = contents.getComponent(0);
            panel.update(group);
            assert contents.getComponent(0) != first : "A new bank snapshot must rebuild";
            group.viewer = new TrackerData.Viewer();
            group.viewer.permissions = new TrackerData.Permissions();
            group.viewer.permissions.banks = false;
            group.viewer.permissions.storage = false;
            panel.update(group);
            assert selector.getItemCount() == 0 && tiles(contents) == 0 : "Revoked permissions must clear bank data";
            group.viewer = null;
            panel.update(group);
            assert tiles(contents) == 800;
            tab(contents, "Tab 1 (Item 10000)").doClick(0);
            selector.setSelectedItem("Other Player");
            assert get(panel, "selectedTab") == null : "Changing member must reset tab selection";
            search.setText("pending");
            panel.clear("Disconnected");
            assert !timer.isRunning() && contents.getComponentCount() == 0 && selector.getItemCount() == 0;
            panel.update(group);
            search.setText("");
            fire(timer);
            assert tiles(contents) == 800 : "Cleared data must render again on reconnection";
        }
        catch (Exception error)
        {
            throw new AssertionError(error);
        }
    }

    private static TrackerData.Group group(int size)
    {
        TrackerData.Member member = new TrackerData.Member();
        member.username = "Test Player";
        member.bankUpdatedAt = 123456;
        member.bank = new ArrayList<>();
        for (int i = 0; i < size; i++)
        {
            TrackerData.BankItem item = new TrackerData.BankItem();
            item.id = 10000 + i;
            item.name = "Item " + item.id;
            item.qty = 1;
            item.tab = i / 200 + 1;
            member.bank.add(item);
        }
        TrackerData.Member other = new TrackerData.Member();
        other.username = "Other Player";
        TrackerData.Group group = new TrackerData.Group();
        group.members = Arrays.asList(member, other);
        return group;
    }

    private static void fire(Timer timer)
    {
        timer.stop();
        for (java.awt.event.ActionListener listener : timer.getActionListeners())
        {
            listener.actionPerformed(new java.awt.event.ActionEvent(timer, 0, "search"));
        }
    }

    private static void rightClick(JButton button)
    {
        button.dispatchEvent(new java.awt.event.MouseEvent(button, java.awt.event.MouseEvent.MOUSE_CLICKED,
            System.currentTimeMillis(), 0, 5, 5, 1, true, java.awt.event.MouseEvent.BUTTON3));
    }

    private static JButton tab(Container container, String label)
    {
        for (Component component : container.getComponents())
        {
            if (component instanceof JButton && label.equals(((JButton) component).getAccessibleContext().getAccessibleName()))
            {
                return (JButton) component;
            }
            if (component instanceof Container)
            {
                JButton found = tab((Container) component, label);
                if (found != null) return found;
            }
        }
        return null;
    }

    private static int tiles(Container container)
    {
        int count = 0;
        for (Component component : container.getComponents())
        {
            if (component.getClass().getSimpleName().equals("ItemTile")) count++;
            if (component instanceof Container) count += tiles((Container) component);
        }
        return count;
    }

    private static Object get(Object instance, String name) throws Exception
    {
        Field field = instance.getClass().getDeclaredField(name);
        field.setAccessible(true);
        return field.get(instance);
    }

    private static void set(Object instance, String name, Object value) throws Exception
    {
        Field field = instance.getClass().getDeclaredField(name);
        field.setAccessible(true);
        field.set(instance, value);
    }
}

package com.bowlsofmayo;

import com.google.gson.GsonBuilder;
import com.sun.net.httpserver.HttpServer;
import java.io.IOException;
import java.lang.reflect.Field;
import java.lang.reflect.Method;
import java.net.InetSocketAddress;
import java.nio.charset.StandardCharsets;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;
import java.util.Queue;
import java.util.concurrent.CopyOnWriteArrayList;
import javax.swing.SwingUtilities;
import net.runelite.api.Skill;
import net.runelite.api.events.StatChanged;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.events.ConfigChanged;
import okhttp3.OkHttpClient;

final class SyncChecks
{
    static void run() throws Exception
    {
        List<Throwable> uiErrors = new CopyOnWriteArrayList<>();
        Thread.UncaughtExceptionHandler[] original = new Thread.UncaughtExceptionHandler[1];
        SwingUtilities.invokeAndWait(() -> {
            original[0] = Thread.currentThread().getUncaughtExceptionHandler();
            Thread.currentThread().setUncaughtExceptionHandler((thread, error) -> uiErrors.add(error));
        });
        try
        {
            checkSharingChanges();
            checkAlertOptOut();
            checkAccessChanges();
            checkEventFailures();
            checkInFlightChange();
            checkSnapshotCaptureChange();
            checkIndependentStatuses();
            checkOptionalMapFailure();
            checkStatusReset();
            checkRestartDiscardsAlerts();
            checkOptionalBankIconFailure();
            checkMixedXpExpiry();
            checkStopDuringUpload();
            checkXpAccessChangeBeforeSend();
            assert uiErrors.isEmpty() : "Asynchronous UI failures: " + uiErrors;
        }
        finally
        {
            SwingUtilities.invokeAndWait(() -> Thread.currentThread().setUncaughtExceptionHandler(original[0]));
        }
        System.out.println("Sync regression checks passed (opt-out, restart, access changes, retries, optional icons, XP expiry).");
    }

    private static void checkIndependentStatuses() throws Exception
    {
        try (Fixture fixture = new Fixture())
        {
            fixture.seed();
            fixture.xpStatus = 500;
            fixture.sendXp();
            assert fixture.status().contains("Live XP not synced");
            fixture.sync();
            assert fixture.status().contains("Live XP not synced") : "Group success must not hide an XP failure";
            fixture.xpStatus = 200;
            fixture.sendXpAfterBackoff();
            assert !fixture.status().contains("Live XP") : "Successful XP retry must clear its own warning";

            fixture.seed();
            fixture.events().add(event("bad", "chat"));
            fixture.eventStatus = 500;
            fixture.sync();
            assert fixture.status().contains("Alerts waiting for retry");
            fixture.sendXpAfterBackoff();
            assert fixture.status().contains("Alerts waiting for retry") : "XP success must not clear alert errors";
            fixture.eventStatus = 200;
            fixture.sync();
            assert fixture.status().isEmpty();

            fixture.seed();
            fixture.xpStatus = 500;
            fixture.sendXpAfterBackoff();
            LiveXpTracker xp = (LiveXpTracker) get(fixture.plugin, "liveXp");
            xp.batch(System.currentTimeMillis()).drops.forEach(drop -> drop.observedAt -= 26000);
            fixture.sendXpAfterBackoff();
            assert fixture.status().contains("expired") : "Expired drops must not be reported as delivered";
            fixture.sync();
            assert fixture.status().contains("expired");
            fixture.settings.xp = false;
            fixture.change("shareLiveXp");
            assert fixture.status().isEmpty() : "Disabling XP must clear XP-specific warnings";

            fixture.events().add(event("bad", "chat"));
            fixture.eventStatus = 500;
            fixture.groupResponse = "{}";
            fixture.sync();
            assert fixture.status().contains("Alerts waiting for retry") && fixture.status().contains("Not synced:") :
                "A group failure must not suppress a new alert failure";
            fixture.eventStatus = 200;
            fixture.sync();
            assert !fixture.status().contains("Alerts waiting") && fixture.status().contains("Not synced:") :
                "Alert recovery must clear its warning even while group downloads fail";
        }
    }

    private static void checkOptionalMapFailure() throws Exception
    {
        try (Fixture fixture = new Fixture())
        {
            fixture.groupResponse = "{\"members\":[{\"username\":\"Teammate\"}]}";
            fixture.mapStatus = 500;
            fixture.sync();
            fixture.drainClientTasks();
            ClanPanel panel = (ClanPanel) get(fixture.plugin, "panel");
            javax.swing.JComboBox<?> selector = (javax.swing.JComboBox<?>) get(panel, "selector");
            assert selector.getItemCount() == 2 : "Map failure must not clear valid member/storage choices";
            assert ((List<?>) get(fixture.plugin, "groupMembers")).size() == 1;
            assert fixture.status().contains("Map icon unavailable");
            fixture.mapStatus = 200;
            set(fixture.plugin, "mapIconFetchedAt", 0L);
            fixture.sync();
            fixture.drainClientTasks();
            assert fixture.status().isEmpty() : "Map recovery must clear the image warning";
            assert selector.getItemCount() == 2;
        }
    }

    private static void checkStatusReset() throws Exception
    {
        for (String key : Arrays.asList("enableConnection", "memberToken", "serverUrl"))
        {
            try (Fixture fixture = new Fixture())
            {
                fixture.seed();
                fixture.xpStatus = 500;
                fixture.sendXp();
                assert fixture.status().contains("Live XP not synced");
                if (key.equals("enableConnection")) fixture.settings.enabled = false;
                fixture.change(key);
                assert !fixture.status().contains("Live XP") : "Access/consent changes must reset old errors";
            }
        }
    }

    private static void checkRestartDiscardsAlerts() throws Exception
    {
        for (String change : Arrays.asList("none", "memberToken", "serverUrl"))
        {
            try (Fixture fixture = new Fixture(); Fixture otherServer = new Fixture())
            {
                fixture.change("memberToken");
                fixture.seed();
                for (String type : Arrays.asList("boss", "loot", "quest"))
                {
                    fixture.events().add(event("old-" + type, type));
                }
                fixture.queueLoot(event("pending-loot", "loot"));
                fixture.plugin.shutDown();
                assert fixture.events().isEmpty() : "Stopping must discard every unsent alert type";
                assert get(fixture.plugin, "snapshot") == null;
                assert !((LiveXpTracker) get(fixture.plugin, "liveXp")).hasPending();
                assert ((List<?>) get(fixture.plugin, "loot")).isEmpty();
                Method enqueue = ClanTrackerPlugin.class.getDeclaredMethod("enqueue", TrackerData.Event.class);
                enqueue.setAccessible(true);
                enqueue.invoke(fixture.plugin, event("stopped-callback", "chat"));
                assert fixture.events().isEmpty() : "Callbacks after shutdown must not refill the queue";
                if (change.equals("memberToken")) fixture.settings.token = "b".repeat(48);
                if (change.equals("serverUrl")) fixture.settings.url = otherServer.settings.url;
                fixture.restart();
                set(fixture.plugin, "account", "New Player");
                fixture.drainClientTasks();
                assert get(fixture.plugin, "account").equals("New Player") :
                    "A reset queued before shutdown must not reset the new lifecycle";
                assert !((Boolean) get(fixture.plugin, "accessResetPending"));
                assert fixture.uploads.isEmpty() && otherServer.uploads.isEmpty() :
                    "Restart must not replay old alerts, even with unchanged access";
                fixture.events().add(event("new", "chat"));
                fixture.sync();
                List<String> uploads = change.equals("serverUrl") ? otherServer.uploads : fixture.uploads;
                assert uploads.size() == 1 && uploads.get(0).contains("\"id\":\"new\"") :
                    "New alerts must still be delivered after restart";
                SwingUtilities.invokeAndWait(() -> {
                    assert fixture.sidebar.getTabCount() == 1 : "Restart must replace, not duplicate, navigation";
                });
            }
        }
    }

    @SuppressWarnings("unchecked")
    private static void checkOptionalBankIconFailure() throws Exception
    {
        try (Fixture fixture = new Fixture())
        {
            fixture.snapshot("Old Player");
            BankSnapshots banks = (BankSnapshots) get(fixture.plugin, "bankSnapshots");
            ((java.util.Map<Integer, String>) get(banks, "itemIcons")).put(995, "synthetic-icon");
            fixture.groupResponse = "{\"members\":[{\"username\":\"Teammate\",\"bank\":[]}]}";
            fixture.iconStatus = 500;
            LiveXpTracker xp = (LiveXpTracker) get(fixture.plugin, "liveXp");
            xp.baseline(Skill.MINING, 1000);
            xp.observe("Old Player", new StatChanged(Skill.MINING, 1005, 9, 9), 9, true, System.currentTimeMillis());
            fixture.xpStatus = 500;
            fixture.sendXp();
            fixture.sync();
            fixture.drainClientTasks();
            javax.swing.JComboBox<?> selector = (javax.swing.JComboBox<?>) get(get(fixture.plugin, "panel"), "selector");
            assert selector.getItemCount() == 2 && ((List<?>) get(fixture.plugin, "groupMembers")).size() == 1 :
                "Optional icon upload failure must retain successfully downloaded group data";
            assert fixture.status().contains("Bank icons not synced") && !fixture.status().contains("Not synced:");
            fixture.iconStatus = 200;
            fixture.sync();
            assert !fixture.status().contains("Bank icons") && fixture.status().contains("Live XP not synced") :
                "Icon recovery must clear only its own warning";
            assert selector.getItemCount() == 2;
            fixture.xpStatus = 200;
            fixture.sendXpAfterBackoff();
            assert fixture.status().isEmpty();
        }
    }

    private static void checkMixedXpExpiry() throws Exception
    {
        try (Fixture fixture = new Fixture())
        {
            fixture.seed();
            LiveXpTracker xp = (LiveXpTracker) get(fixture.plugin, "liveXp");
            long now = System.currentTimeMillis();
            String expiredId = xp.batch(now).drops.get(0).id;
            xp.batch(now).drops.get(0).observedAt -= 26000;
            xp.observe("Old Player", new StatChanged(Skill.MINING, 1040, 9, 9), 9, true, now);
            fixture.xpStatus = 500;
            fixture.sendXp();
            assert fixture.status().contains("expired") && fixture.status().contains("Live XP not synced") :
                "Expiration must be reported even when the remaining fresh batch fails";
            assert fixture.uploads.stream().noneMatch(value -> value.contains(expiredId)) :
                "Expired live drops must never be transmitted";
            assert xp.hasPending() : "Failed fresh drops must remain queued";
            fixture.xpStatus = 200;
            fixture.sendXpAfterBackoff();
            assert !xp.hasPending();
            assert fixture.status().contains("expired") && !fixture.status().contains("Live XP not synced") :
                "Delivery recovery must not erase the lost-drop notification";
            fixture.sync();
            assert fixture.status().contains("expired") : "Group recovery must not erase expiration";
            fixture.settings.xp = false;
            fixture.change("shareLiveXp");
            assert fixture.status().isEmpty() : "Changing XP consent must reset the expiration notification";
        }
    }

    private static void checkStopDuringUpload() throws Exception
    {
        try (Fixture fixture = new Fixture())
        {
            fixture.seed();
            fixture.afterSnapshot = fixture.plugin::shutDown;
            fixture.sync();
            assert fixture.uploads.size() == 1 : "Only the already-started snapshot may finish";
            assert fixture.events().isEmpty() && fixture.groupReads == 0 :
                "Stopping during an upload must discard alerts and prevent subsequent old-lifecycle work";
            fixture.afterSnapshot = null;
            fixture.settings.token = "b".repeat(48);
            fixture.restart();
            assert fixture.uploads.size() == 1 : "Restart must not replay discarded in-flight session data";
        }
    }

    private static void checkXpAccessChangeBeforeSend() throws Exception
    {
        try (Fixture fixture = new Fixture())
        {
            fixture.seed();
            fixture.settings.onTokenRead = () -> {
                fixture.settings.onTokenRead = null;
                fixture.settings.token = "b".repeat(48);
                fixture.change("memberToken");
            };
            fixture.sendXp();
            assert fixture.uploads.isEmpty() : "Access changes during request setup must invalidate the XP batch";
            assert !((LiveXpTracker) get(fixture.plugin, "liveXp")).hasPending();
        }
    }

    private static void checkSharingChanges() throws Exception
    {
        for (String key : Arrays.asList("shareBank", "shareLocation", "shareChat", "bossAlerts",
            "dropAlerts", "questAlerts", "shareLiveXp", "enableConnection"))
        {
            try (Fixture fixture = new Fixture())
            {
                fixture.seed();
                fixture.settings.disable(key);
                fixture.change(key);
                fixture.sync();
                assert fixture.uploads.stream().noneMatch(value -> value.startsWith("/v1/snapshot")) :
                    key + " must invalidate cached snapshots";
                boolean chatDisabled = key.equals("shareChat") || key.equals("enableConnection");
                assert fixture.uploads.stream().anyMatch(value -> value.contains("old chat")) == !chatDisabled :
                    "Unrelated sharing choices must be preserved: " + key;
                if (key.equals("shareBank"))
                {
                    fixture.drainClientTasks();
                    assert get(fixture.plugin, "bank") == null && get(fixture.plugin, "groupStorage") == null :
                        "Changing bank sharing must forget previously collected containers";
                    fixture.settings.bank = true;
                    fixture.change(key);
                    fixture.sync();
                    assert fixture.uploads.stream().noneMatch(value -> value.startsWith("/v1/snapshot")) :
                        "Re-enabling sharing must not restore an old snapshot";
                }
            }
        }
        try (Fixture fixture = new Fixture())
        {
            fixture.seed();
            fixture.settings.bank = false;
            fixture.settings.location = false;
            fixture.settings.chat = false;
            fixture.sync();
            assert fixture.uploads.stream().noneMatch(value -> value.contains("\"bank\":[{") ||
                value.contains("\"x\":3200") || value.contains("old chat")) :
                "Send-time consent checks must protect cached data even before config callbacks run";
        }
    }

    private static void checkAccessChanges() throws Exception
    {
        for (String key : Arrays.asList("memberToken", "serverUrl"))
        {
            try (Fixture fixture = new Fixture(); Fixture otherServer = new Fixture())
            {
                fixture.seed();
                fixture.settings.token = "b".repeat(48);
                boolean serverChanged = key.equals("serverUrl");
                if (serverChanged)
                {
                    fixture.settings.url = otherServer.settings.url;
                }
                fixture.change(key);
                assert get(fixture.plugin, "snapshot") == null : "Access changes must invalidate snapshots immediately";
                assert fixture.events().isEmpty() : "Access changes must discard old alerts";
                LiveXpTracker xp = (LiveXpTracker) get(fixture.plugin, "liveXp");
                assert !xp.hasPending() : "Access changes must discard old live XP immediately";
                fixture.sync();
                fixture.sendXp();
                assert fixture.uploads.isEmpty() && otherServer.uploads.isEmpty() :
                    "No old data may be uploaded with new credentials";
                Method enqueue = ClanTrackerPlugin.class.getDeclaredMethod("enqueue", TrackerData.Event.class);
                enqueue.setAccessible(true);
                enqueue.invoke(fixture.plugin, event("stale-callback", "chat"));
                assert fixture.events().isEmpty() : "Old client callbacks must not refill the queue while access is resetting";
                fixture.drainClientTasks();
                assert get(fixture.plugin, "account") == null : "Access changes must reset account state";
                fixture.snapshot("New Player");
                fixture.sync();
                List<String> uploads = serverChanged ? otherServer.uploads : fixture.uploads;
                List<String> authorization = serverChanged ? otherServer.authorization : fixture.authorization;
                assert uploads.stream().anyMatch(value -> value.contains("New Player"));
                assert uploads.stream().noneMatch(value -> value.contains("Old Player"));
                assert authorization.stream().allMatch(value -> value.equals("Bearer " + fixture.settings.token));
            }
        }
    }

    private static void checkAlertOptOut() throws Exception
    {
        String[] keys = {"shareChat", "bossAlerts", "dropAlerts", "questAlerts"};
        String[] types = {"chat", "boss", "loot", "quest"};
        for (int i = 0; i < keys.length; i++)
        {
            try (Fixture fixture = new Fixture())
            {
                for (String type : types) fixture.events().add(event(type, type));
                fixture.settings.disable(keys[i]);
                fixture.change(keys[i]);
                String disabledType = types[i];
                assert fixture.events().size() == 3 : "Opt-out must remove only the affected alert type";
                assert fixture.events().stream().noneMatch(event -> event.type.equals(disabledType));
                fixture.sync();
                assert fixture.uploads.size() == 3 : "Unrelated alerts must still be sent";
            }
        }
        try (Fixture fixture = new Fixture())
        {
            fixture.seed();
            LiveXpTracker xp = (LiveXpTracker) get(fixture.plugin, "liveXp");
            fixture.settings.disable("shareLiveXp");
            fixture.change("shareLiveXp");
            assert !xp.hasPending() : "Disabling live XP must clear old drops immediately";
            fixture.sendXp();
            assert fixture.uploads.isEmpty() : "Disabling live XP must stop uploads";
            fixture.drainClientTasks();
            assert !xp.hasPending();
            fixture.settings.xp = true;
            fixture.change("shareLiveXp");
            fixture.drainClientTasks();
            xp.baseline(Skill.MINING, 2000);
            xp.observe("Old Player", new StatChanged(Skill.MINING, 2010, 9, 9), 9, true, System.currentTimeMillis());
            fixture.sendXp();
            assert fixture.uploads.size() == 1 && fixture.uploads.get(0).contains("\"amount\":10") :
                "Re-enabling live XP must send only newly observed drops";
        }
    }

    private static void checkEventFailures() throws Exception
    {
        for (int code : new int[]{400, 403, 413, 422, 401, 429, 500})
        {
            try (Fixture fixture = new Fixture())
            {
                fixture.eventStatus = code;
                fixture.events().add(event("bad", "chat"));
                fixture.events().add(event("good", "chat"));
                fixture.sync();
                assert fixture.groupReads == 1 : "Rejected alert must not block group refresh for HTTP " + code;
                boolean permanent = code == 400 || code == 403 || code == 413 || code == 422;
                assert fixture.events().size() == (permanent ? 0 : 2) :
                    "Permanent rejection must discard only rejected alerts; temporary errors must retain the queue";
                fixture.eventStatus = 200;
                fixture.sync();
                assert fixture.events().isEmpty() : "Temporary failures must retry successfully";
                assert fixture.groupReads == 2;
            }
        }
    }

    private static void checkInFlightChange() throws Exception
    {
        try (Fixture fixture = new Fixture())
        {
            fixture.seed();
            fixture.afterSnapshot = () -> {
                try { fixture.change("memberToken"); }
                catch (Exception error) { throw new AssertionError(error); }
            };
            fixture.sync();
            assert fixture.uploads.size() == 1 : "Already-started request may finish, but stale work must stop";
            assert fixture.groupReads == 0 : "Old access revision must not fetch or display group data";
        }
    }

    private static void checkSnapshotCaptureChange() throws Exception
    {
        try (Fixture fixture = new Fixture())
        {
            fixture.settings.location = false;
            fixture.settings.bank = false;
            fixture.snapshot("Old Player");
            java.util.concurrent.atomic.AtomicBoolean changed = new java.util.concurrent.atomic.AtomicBoolean();
            net.runelite.api.Client client = (net.runelite.api.Client) java.lang.reflect.Proxy.newProxyInstance(
                net.runelite.api.Client.class.getClassLoader(), new Class<?>[]{net.runelite.api.Client.class},
                (proxy, method, arguments) -> {
                    switch (method.getName())
                    {
                        case "getVarpValue": return 0;
                        case "getSkillExperience": return 1000;
                        case "getRealSkillLevel":
                            if (changed.compareAndSet(false, true))
                            {
                                fixture.settings.chat = false;
                                fixture.change("shareChat");
                            }
                            return 9;
                        default: throw new AssertionError("Unexpected client access: " + method.getName());
                    }
                });
            set(fixture.plugin, "client", client);
            Method capture = ClanTrackerPlugin.class.getDeclaredMethod("captureSnapshot");
            capture.setAccessible(true);
            capture.invoke(fixture.plugin);
            assert changed.get() && get(fixture.plugin, "snapshot") == null :
                "A snapshot started before a settings change must not be published afterward";
        }
    }

    private static TrackerData.Event event(String id, String type)
    {
        TrackerData.Event event = new TrackerData.Event();
        event.id = id;
        event.username = "Old Player";
        event.type = type;
        event.message = "old chat";
        return event;
    }

    private static void set(Object target, String name, Object value) throws Exception
    {
        Field field = target.getClass().getDeclaredField(name);
        field.setAccessible(true);
        field.set(target, value);
    }

    private static Object get(Object target, String name) throws Exception
    {
        Field field = target.getClass().getDeclaredField(name);
        field.setAccessible(true);
        return field.get(target);
    }

    private static final class Settings implements ClanTrackerConfig
    {
        String url;
        String token = "a".repeat(48);
        boolean enabled = true;
        boolean bank = true;
        boolean location = true;
        boolean chat = true;
        boolean boss = true;
        boolean loot = true;
        boolean quest = true;
        boolean xp = true;
        Runnable onTokenRead;
        void disable(String key)
        {
            switch (key)
            {
                case "enableConnection": enabled = false; break;
                case "shareBank": bank = false; break;
                case "shareLocation": location = false; break;
                case "shareChat": chat = false; break;
                case "bossAlerts": boss = false; break;
                case "dropAlerts": loot = false; break;
                case "questAlerts": quest = false; break;
                case "shareLiveXp": xp = false; break;
                default: throw new AssertionError("Unexpected setting: " + key);
            }
        }
        public boolean enableConnection() { return enabled; }
        public boolean shareBank() { return bank; }
        public boolean shareLocation() { return location; }
        public boolean shareChat() { return chat; }
        public boolean bossAlerts() { return boss; }
        public boolean dropAlerts() { return loot; }
        public boolean questAlerts() { return quest; }
        public boolean shareLiveXp() { return xp; }
        public String serverUrl() { return url; }
        public String memberToken()
        {
            if (onTokenRead != null) onTokenRead.run();
            return token;
        }
    }

